def card(file,title,subtitle,sections,bottom,note,accent='green'):
    return dict(file=file,eyebrow='',title=title,subtitle=subtitle,accent=accent,
                sections=[dict(heading=h,body=b) for h,b in sections],bottom=bottom,small_note=note)


